--
-- Table structure for table `routes`
--

DROP TABLE IF EXISTS `routes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `routes` (
  `constructor_id` varchar(50) NOT NULL,
  `circuit_id` varchar(50) NOT NULL,
  `transport_mode` varchar(10) NOT NULL COMMENT 'road oppure air',
  `distance_km` decimal(7,1) NOT NULL COMMENT 'road: OSRM; air: linea d aria',
  `travel_hours` decimal(5,2) DEFAULT NULL COMMENT 'road: ore di guida OSRM; air: NULL',
  PRIMARY KEY (`constructor_id`,`circuit_id`),
  KEY `routes_ibfk_2` (`circuit_id`),
  CONSTRAINT `routes_ibfk_1` FOREIGN KEY (`constructor_id`) REFERENCES `constructors` (`constructor_id`),
  CONSTRAINT `routes_ibfk_2` FOREIGN KEY (`circuit_id`) REFERENCES `circuits` (`circuit_id`),
  CONSTRAINT `routes_mode_chk` CHECK (`transport_mode` in ('road','air'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

